@Path("/async")
public class AsyncResource {

    @Inject
    private ManagedExecutorService executor;

    @GET
    @Path("/process")
    public void processAsync(@Suspended AsyncResponse response) {
        response.setTimeout(30, TimeUnit.SECONDS);
        response.setTimeoutHandler(ar -> 
            ar.resume(Response.status(Status.SERVICE_UNAVAILABLE).build())
        );

        executor.submit(() -> {
            try {
                Result result = performLongOperation();
                response.resume(Response.ok(result).build());
            } catch (Exception e) {
                response.resume(e);
            }
        });
    }
}

@ApplicationScoped
