try {
    // OSGi service lookup
    ServiceReference<?> ref = context.getServiceReference(MyService.class);
    if (ref == null) {
        throw new ServiceUnavailableException("MyService not available");
    }
    MyService service = (MyService) context.getService(ref);
    // Use service
} catch (InvalidSyntaxException e) {
    // Log and handle invalid service filter
    logger.error("Invalid service filter", e);
    throw new IllegalStateException("Configuration error", e);
}

ServiceRegistration<?> registration = null;
try {
    registration = context.registerService(
        MyService.class.getName(), 
        new MyServiceImpl(), 
        null
    );
    // Use service
} finally {
    if (registration != null) {
        try {
            registration.unregister();
        } catch (IllegalStateException e) {
            // Already unregistered, ignore
        }
    }
}

@ApplicationScoped
public class CacheService {
    // Thread-safe concurrent map
    private final ConcurrentHashMap<String, Object> cache = 
        new ConcurrentHashMap<>();

    // Atomic operations
    private final AtomicLong hitCount = new AtomicLong();

    public Object get(String key) {
        Object value = cache.get(key);
        if (value != null) {
            hitCount.incrementAndGet();
        }
        return value;
    }
}

@ApplicationScoped
public class AsyncProcessor {

    @Resource
    private ManagedExecutorService executor;

    public CompletableFuture<Result> processAsync(Request request) {
        return CompletableFuture.supplyAsync(
            () -> process(request),
            executor
        );
    }
}

comment_format.multi_line:
Use for multi-line changes:
// Liberty Change Start
[modified code]
// Liberty Change End

examples.example:
// Original RESTEasy code:
private ClassLoader classLoader = Thread.currentThread().getContextClassLoader();

// Modified for Liberty:
private ClassLoader classLoader = getLibertyClassLoader(); // Liberty Change

// Original RESTEasy code:
public void initialize() {
    loadProviders();
    registerDefaults();
}

// Modified for Liberty:
public void initialize() {
    // Liberty Change Start
    if (isLibertyEnvironment()) {
        loadLibertyProviders();
    } else {
        loadProviders();
    }
    // Liberty Change End
    registerDefaults();
}
